					},
					{
						"item": "viz_ap_name",
						"position": {
							"h": 94,
							"w": 720,
							"x": 720,
							"y": 0
						},
						"type": "block"
					},
					{
						"item": "viz_ap_ip",
						"position": {
							"h": 97,
