							"x": 720,
							"y": 191
						},
						"type": "block"
					},
					{
						"item": "viz_current_rssi",
						"position": {
							"h": 300,
							"w": 226,
							"x": 1214,
							"y": 291
						},
						"type": "block"
					},
					{
						"item": "viz_current_snr",
						"position": {
							"h": 300,
							"w": 226,
							"x": 1214,
							"y": 591
						},
						"type": "block"
					},
					{
						"item": "viz_current_speed",
						"position": {
							"h": 300,
							"w": 226,
							"x": 1214,
							"y": 891
						},
						"type": "block"
					}
				],
				"type": "grid"
			}
		},
		"options": {},
		"tabs": {
			"items": [
				{
					"label": "New tab",
					"layoutId": "layout_1"
				}
			]
		}
	},
	"applicationProperties": {}
}
